        dqc_dt[c] = (wqc - qc_in[c]) * pc.inv_dt;
        dqr_dt[c] = (wqr - qr_in[c]) * pc.inv_dt;
        dqi_dt[c] = (wqi - qi_in[c]) * pc.inv_dt;
        dqs_dt[c] = (wqs - qs_in[c]) * pc.inv_dt;
        dqg_dt[c] = (wqg - qg_in[c]) * pc.inv_dt;
        dqh_dt[c] = (wqh - qh_in[c]) * pc.inv_dt;

        // Temperature tendency -> potential-temperature tendency (Exner),
        // mirroring thermodynamics::temperature_tendency_to_theta.
        float dT_dt  = dT_sum * pc.inv_dt;
        float dtheta = 0.0;
